188:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage::IFD& ifd) {
189:   struct AutoRestore {
190:     std::ostream& os_;
191:     std::ios_base::fmtflags flags_;
192:     AutoRestore(std::ostream& os) : os_(os), flags_(os.flags()) {}
193:     ~AutoRestore() { os_.flags(flags_); }
194:   } autoRestore(os);
195: 
196:   os << "TIFF IFD:\n"
197:      << "  Entry count: " << ifd.entries().size() << "\n";
198:   int i = 0;
199:   for (const auto& entry : ifd.entries()) {
200:     os << std::setw(4) << i++ << "# " << entry.second;
201:   }
202:   return os;
203: }
204: 
205:   inline std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage& image) {
206:   struct AutoRestore {
207:     std::ostream& os_;
208:     std::ios_base::fmtflags flags_;
209:     AutoRestore(std::ostream& os) : os_(os), flags_(os.flags()) {}
210:     ~AutoRestore() { os_.flags(flags_); }
211:   } autoRestore(os);
212: 
213:   os << "TIFF IMAGE START -----------------------\n"
214:      << image.header()
215:      << "IFD count: " << image.ifds().size() << "\n";
216:   for (int i = 0; i < image.ifds().size(); ++i) {
217:     os << std::setw(2) << i << ") " << image.ifds()[i];
218:   }
219:   os << "TIFF IMAGE END -------------------------\n";
220:   return os;
221: }
