307:     static std::vector<int> getBitsPerSample(const TiffImage::IFD& ifd)
308:     {
309:       if (ifd.entries().contains(Tag::BitsPerSample)) {
310:         return getIntVec(ifd, Tag::BitsPerSample);
311:       }
312:       return { 1 }; // default value if missing
