315:     static RectInfo getRectInfo(const TiffImage::IFD& ifd)
316:     {
317:       const std::vector<int> bitsPerSampleVec = getBitsPerSample(ifd);
318:       if (bitsPerSampleVec.empty()
319:         || std::any_of(bitsPerSampleVec.begin(), bitsPerSampleVec.end(),
320:           [&](int n) { return n != bitsPerSampleVec.front(); })) {
321:          throw FormatNotSupportedError("Unsupported bits per sample");
322:       }
323:       const int bitsPerSample = bitsPerSampleVec.front();
324:       const int samplesPerPixel = getInt(ifd, Tag::SamplesPerPixel, 1);
325:       const int planarConfiguration = getInt(ifd, Tag::PlanarConfiguration, 1);
326: 
327:       const int imageWidth = getWidth(ifd);
328:       const int imageHeight = getHeight(ifd);
329: 
330:       const int rowsPerStrip = getInt(ifd, Tag::RowsPerStrip, imageHeight);
331: 
332:       const int tileWidth = getInt(ifd, Tag::TileWidth, imageWidth);
333:       const int tileHeight = getInt(ifd, Tag::TileLength, rowsPerStrip);
334:       const int tileChannels = (planarConfiguration == 1 ? samplesPerPixel : 1);
335:       const int tileStride = (tileWidth * tileChannels * bitsPerSample + 7) / 8;
336: 
337:       return { tileWidth, tileHeight, tileStride, bitsPerSample };
338:     }
339: 
340:     template <typename SrcType, typename DstType, typename UnaryOp>
341:     void copyRectangles(
342:       const TiffImage::ImageData& imageData,  // source pixel data
343:       const RectInfo& rectInfo,               // source rectangle info
344:       size_t channels,                        // source image channels
345:       size_t planes,                          // source image planes
346:       bool equalsHostByteOrder,               // source data byte order
347:       UnaryOp&& op)
348:     {
349:       const int imageWidth = image_.width;
350:       const int imageHeight = image_.height;
351: 
352:       const int rectAcross = (imageWidth + (rectInfo.width - 1)) / rectInfo.width;
353:       const int rectDown = (imageHeight + (rectInfo.height - 1)) / rectInfo.height;
354:       const int rectsInPlane = rectAcross * rectDown;
355: 
356:       const int rectsInImage = rectAcross * rectDown * planes;
357:       if (rectsInImage != imageData.size()) {
358:         throw std::runtime_error("Rectangle count mismatch");
359:       }
360: 
361:       for (int plane = 0; plane < planes; ++plane) {
362:         for (int rectY = 0; rectY < rectDown; ++rectY) {
363:           for (int rectX = 0; rectX < rectAcross; ++rectX) {
364:             const auto& rectData = imageData[plane * rectsInPlane + rectY * rectAcross + rectX];
365:             auto currRectInfo = rectInfo;
366:             currRectInfo.width = std::min(rectInfo.width, imageWidth - rectX * rectInfo.width);
367:             currRectInfo.height = std::min(rectInfo.height, imageHeight - rectY * rectInfo.height);
368:             copyRectangle<SrcType, DstType, UnaryOp>(
369:               rectData,                    // source pixel data
370:               currRectInfo,                // source rectangle info
371:               channels,                    // source image channels
372:               equalsHostByteOrder,         // source data byte order
373:               plane,                       // destination plane
374:               rectX * rectInfo.width,      // destination column
375:               rectY * rectInfo.height,     // destination row
376:               std::forward<UnaryOp>(op));
377:           }
378:         }
379:       }
380:     }
381: 
382:     template <typename SrcType, typename DstType, typename UnaryOp>
383:     void copyRectangle(
384:       const std::vector<std::byte>& rectData, // source pixel data
385:       const RectInfo& rectInfo,               // source rectangle info
386:       size_t channels,                        // source image channels
387:       bool equalsHostByteOrder,               // source data byte order
388:       size_t dstPlane,                        // destination plane
389:       size_t dstX,                            // destination column
390:       size_t dstY,                            // destination row
391:       UnaryOp&& op)
392:     {
393:       constexpr size_t bitsPerSrcPixel = 8 * sizeof(SrcType);
394:       const auto* src = rectData.data();
395:       const auto* srcEnd = rectData.data() + rectData.size();
396: 
397:       size_t countAvail = 0;
398:       SrcType bitsAvail = 0;
399: 
400:       using ValueType = std::invoke_result_t<UnaryOp, DstType>;
401: 
402:       const size_t dstRowStride = image_.rowStride / sizeof(ValueType);
403:       const size_t dstColStride = image_.colStride / sizeof(ValueType);
404:       const size_t dstChanStride = image_.chanStride / sizeof(ValueType);
405:       const size_t dstPlaneStride = dstRowStride * image_.height;
406:       auto* dst = image_.dataPtr<ValueType>()
407:         + dstPlane * dstPlaneStride
408:         + dstY * dstRowStride
409:         + dstX * dstColStride;
410: 
411:       const auto* srcRow = src;
412:       auto* dstRow = dst;
413: 
414:       auto loop = [&](auto processor) {
415:         for (int row = 0; row < rectInfo.height; ++row) {
416:           if (src >= srcEnd) {
417:             // We've reached the end of the source tile
418:             throw std::runtime_error("Unexpected end of source tile");
419:           }
420:           srcRow = src;
421:           dstRow = dst;
422:           for (int col = 0; col < rectInfo.width; ++col) {
423:             auto* dstChan = dstRow;
424:             for (int chan = 0; chan < channels; ++chan) {
425:               DstType value = processor();
426:               *dstChan = std::invoke(op, value);
427:               dstChan += dstChanStride;
428:             }
429:             dstRow += dstColStride;
430:           }
431:           src += rectInfo.stride;
432:           dst += dstRowStride;
433:           // flush partial words when the row is complete
434:           if (countAvail > 0) {
435:             countAvail = 0;
436:             bitsAvail = 0;
437:           }
438:         }
439:       };
440: 
441:       auto process_word = [&]() -> DstType {
442:         DstType value = *reinterpret_cast<const SrcType*>(&(*srcRow));
443:         srcRow += sizeof(SrcType);
444:         if (!equalsHostByteOrder) {
445:           value = swap(value);
446:         }
447:         return value;
448:       };
449: 
450:       auto process_bits = [&]() -> DstType {
451:         size_t count = 0;
452:         DstType value = 0;
453:         while (count < rectInfo.bitsPerSample) {
454:           // make sure we have some bits available
455:           if (countAvail == 0) {
456:             bitsAvail = *reinterpret_cast<const SrcType*>(&(*srcRow));
457:             srcRow += sizeof(SrcType);
458:             if (!equalsHostByteOrder) {
459:               bitsAvail = swap(bitsAvail);
460:             }
461:             countAvail = bitsPerSrcPixel;
462:           }
463:           // consume available bits
464:           const size_t n = std::min(rectInfo.bitsPerSample - count, countAvail);
465:           value <<= n;
466:           value |= (bitsAvail >> (bitsPerSrcPixel - n));
467:           count += n;
468:           // update available bits
469:           countAvail -= n;
470:           bitsAvail <<= n;
471:         }
472:         assert(count == rectInfo.bitsPerSample);
473:         return value;
474:       };
475: 
476:       if (rectInfo.bitsPerSample == bitsPerSrcPixel) {
477:         // Fast path: bits per sample matches source pixel size
478:         loop(process_word);
479:       } else {
480:         // Slow path: bits per sample does not match source pixel size
481:         loop(process_bits);
482:       }
483:     }
484: 
485:     void invertColors() {
486:       uint8_t* data = image_.dataPtr<uint8_t>();
487:       for (size_t i = 0; i < image_.data.size(); ++i) {
488:         data[i] = ~data[i];
489:       }
490:     }
491:   };
